javaproject.java:
package pk_SJSf;

import lotus.domino.*;
import java.io.BufferedReader;
import java.io.File;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.OutputStream;
import java.io.OutputStreamWriter;
import java.io.PrintWriter;
import java.net.HttpURLConnection;
import java.net.URL;
import java.net.URLConnection;
import java.nio.file.Files;
import javax.net.ssl.HttpsURLConnection;

public class cl_SJSf {
	public String EnvoyerTransaction(String p_URL, String p_CleIntegration, String p_JsonContent, String p_Fichier) {
//		public String EnvoyerTransaction(String p_URL, String p_CleIntegration, String p_JsonContent, String p_Fichier1, String p_Fichier2, String p_Fichier3) {
			File uploadFile1;
			int responseCode = 0;

			try {
				String charset = "UTF-8";
				String boundary = Long.toHexString(System.currentTimeMillis());
				String CRLF = "\r\n"; // Line separator used in multipart/form-data.

				HttpsURLConnection connection = null;
				URL url = new URL(p_URL);
				connection = (HttpsURLConnection) url.openConnection();
				connection.setDoOutput(true);
				connection.setDoInput(true);
				connection.setRequestMethod("POST");
				connection.setRequestProperty("Content-Type", "multipart/form-data; boundary=" + boundary);
				connection.setRequestProperty("Authorization", "Bearer " + p_CleIntegration);
				connection.setRequestProperty("Accept", "application/json; esl-api-version=11.0");
				OutputStream output = connection.getOutputStream();
				PrintWriter writer = new PrintWriter(new OutputStreamWriter(output, charset), true);

				try {

					// add json payload
					writer.append("--" + boundary).append(CRLF);
					writer.append("Content-Disposition: form-data; name=\"entity_document\"").append(CRLF);
					writer.append("Content-Type: application/json; charset=" + charset).append(CRLF);
					writer.append(CRLF).append(p_JsonContent).append(CRLF).flush();

					// Add pdf file
					if (p_Fichier != "") {

						uploadFile1 = new File(p_Fichier);
						writer.append("--" + boundary).append(CRLF);
						writer.append("Content-Type: " + URLConnection.guessContentTypeFromName(uploadFile1.getName()))
						.append(CRLF);
						writer.append("Content-Disposition: form-data; name=\"Body\"; filename=\"" + uploadFile1.getName() + "\"")
						.append(CRLF);
						writer.append(CRLF).flush();
						Files.copy(uploadFile1.toPath(), output);
						output.flush();
						writer.append(CRLF).flush();
					}

					// End of multipart/form-data.
					writer.append("--" + boundary + "--").append(CRLF).flush();
				} catch (IOException ex) {
					System.err.println(ex);
					return("ERR1: " + ex);
				}

				// get and write out response code
				responseCode = ((HttpURLConnection) connection).getResponseCode();
				System.out.println(responseCode);

				if (responseCode == 200 || responseCode == 201) {

					// get and write out response
					BufferedReader in = new BufferedReader(new InputStreamReader(connection.getInputStream()));
					String inputLine;
					StringBuffer response = new StringBuffer();

					while ((inputLine = in.readLine()) != null) {
						response.append(inputLine);
					}
					in.close();

					// print result
					System.out.println(response.toString());
					return(String.valueOf(responseCode) + ";" + response.toString());

				} else {

					// get and write out response
					BufferedReader in = new BufferedReader(new InputStreamReader(connection.getErrorStream()));
					String inputLine;
					StringBuffer response = new StringBuffer();

					while ((inputLine = in.readLine()) != null) {
						response.append(inputLine);
					}
					in.close();

					// print result
					System.out.println(response.toString());
					return(String.valueOf(responseCode) + ";" + response.toString());
				}

			} catch(Exception e) {
				e.printStackTrace();
				return("ERR0: " + String.valueOf(responseCode) + " - " + e);
			}
		}
}

